def U_(x):
 f=(ord(x[1])-49)*16+ord(x[0])-97
 t=(ord(x[3])-49)*16+ord(x[2])-97
 m=f|t<<7
 if len(x)==5:m|=("nbrq".index(x[4])+2)<<14
 return m
while 1:
 gm=p("/game",{})
